#!/usr/bin/env bash
# {{NAME}} — generated by TERMy ({{LANG}})
set -euo pipefail

bubble_sort() {
    local arr=("$@") n=${#arr[@]} i j tmp
    printf 'Before: %s\n' "${arr[*]}"
    for ((i = 0; i < n; i++)); do
        for ((j = 0; j < n - i - 1; j++)); do
            if (( arr[j] > arr[j+1] )); then
                tmp=${arr[j]}; arr[j]=${arr[j+1]}; arr[j+1]=$tmp
            fi
        done
    done
    printf 'After:  %s\n' "${arr[*]}"
}

bubble_sort {{ARRAY}}